def min_max(nums):
    return min(nums), max(nums)   # 返回(最小值,最大值)

nums = [3, 1, 4, 1, 5]
mn, mx = min_max(nums)   # 拆包接收
print(mn, mx)   # 1 5

def factorial(n):
    return n * factorial(n - 1)   # ❌想想这会有问题吗?

# 会无限调用,永远停不下来!因为没有出口

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

n = int(input())
print(factorial(n))
